INSERT INTO `course` (`id`, `teacher_id`, `course_name`, `course_code`, `credit`, `semester`, `description`, `created_at`) VALUES (3,215,'信息技术','IT-01',2,'2026-2027学年第一学期','智能归科自动创建｜4 个课件：快速排序算法动画课件、二分查找算法（实战应用）、二分查找算法（进阶版）、二分查找算法（基础版）','2026-11-10 20:51:21');
