INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (9,4,'下列关于勾股定理的描述，正确的是？','[\"A. 任意三角形都满足两边平方和等于第三边平方\",\"B. 直角三角形两直角边的平方和等于斜边的平方\",\"C. 直角三角形两边长度之和等于第三边长度\",\"D. 勾股定理是近代从西方传入中国的数学成果\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (10,4,'已知直角三角形的斜边长为10，其中一条直角边长为6，则另一条直角边的长度为？','[\"A. 4\",\"B. 6\",\"C. 8\",\"D. 12\"]','C','objective',10);
