INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (13,6,'光合作用的场所主要是植物细胞中的哪个结构？','[\"A. 线粒体\",\"B. 叶绿体\",\"C. 细胞核\",\"D. 液泡\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (14,6,'下列关于光合作用暗反应阶段的说法，正确的是？','[\"A. 必须在黑暗条件下才能进行\",\"B. 发生在类囊体薄膜上\",\"C. 完成二氧化碳的固定和有机物的生成\",\"D. 主要产物是氧气\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (18,8,'根据牛顿第二定律，物体加速度的方向与下列哪个物理量的方向始终相同？','[\"A. 物体的速度方向\",\"B. 物体所受合外力的方向\",\"C. 物体位移的方向\",\"D. 物体运动的方向\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (19,8,'一个质量为4kg的物体，在光滑水平面上受到水平方向8N的合外力作用，其加速度大小为？','[\"A. 0.5 m/s²\",\"B. 2 m/s²\",\"C. 4 m/s²\",\"D. 32 m/s²\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (20,8,'下列关于牛顿第二定律的说法，错误的是？','[\"A. 加速度与合外力同时产生、同时消失\",\"B. 质量越大的物体惯性越大，相同力下加速度越小\",\"C. 物体的速度方向一定与合外力方向相同\",\"D. 垂直方向上的力各自独立产生加速度\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (21,9,'快速排序算法的平均时间复杂度是？','[\"A. O(n)\",\"B. O(n²)\",\"C. O(nlogn)\",\"D. O(logn)\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (22,9,'快速排序的核心操作「分区」完成后，基准元素的特点是？','[\"A. 是数组中最小的元素\",\"B. 位于数组的最终正确位置\",\"C. 是数组中最大的元素\",\"D. 需要移动到数组两端\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (23,10,'实验室用高锰酸钾制取氧气时，试管口塞一团棉花的作用是什么？','[\"A. 防止高锰酸钾粉末进入导管\",\"B. 防止产生的氧气过快逸出\",\"C. 吸收反应产生的热量\",\"D. 便于观察反应颜色变化\"]','A','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (24,10,'用排水法收集氧气时，什么时候开始收集气体最合适？','[\"A. 刚开始有气泡冒出时\",\"B. 气泡连续均匀冒出时\",\"C. 反应进行5分钟后\",\"D. 酒精灯熄灭后\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (25,10,'实验结束后，正确的操作顺序是？','[\"A. 先熄灭酒精灯，再移出导管\",\"B. 先移出导管，再熄灭酒精灯\",\"C. 同时进行两步操作\",\"D. 顺序没有要求\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (26,11,'实验室加热高锰酸钾制取氧气时，试管口放置一团棉花的作用是？','[\"A. 防止产生的氧气太快逸出\",\"B. 防止高锰酸钾粉末进入导管\",\"C. 吸收反应产生的水蒸气\",\"D. 保持试管内温度恒定\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (27,11,'用向上排空气法收集氧气时，验满的正确方法是？','[\"A. 将带火星的木条伸入集气瓶内部\",\"B. 将燃着的木条放在集气瓶口\",\"C. 将带火星的木条放在集气瓶口\",\"D. 观察瓶内气体颜色变化\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (28,11,'下列关于实验室制氧气操作“查装定点收离熄”，说法错误的是？','[\"A. “查”是指检查装置气密性\",\"B. “定”时试管口应略向下倾斜\",\"C. “收”时一开始冒气泡就立即收集\",\"D. “离”在“熄”之前，防止水倒吸\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (29,12,'中国共产党第一次全国代表大会召开的时间是？','[\"A. 1919年5月\",\"B. 1920年7月\",\"C. 1921年7月\",\"D. 1922年7月\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (30,12,'下列哪一事件标志着工人阶级开始以独立姿态登上中国政治舞台，为中国共产党成立奠定了阶级基础？','[\"A. 新文化运动\",\"B. 五四运动\",\"C. 辛亥革命\",\"D. 十月革命\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (31,12,'中国第一个共产党早期组织的建立地点是？','[\"A. 北京\",\"B. 广州\",\"C. 长沙\",\"D. 上海\"]','D','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (32,12,'结合所学知识，分析五四运动为什么成为中国新民主主义革命的开端，并谈谈它与中国共产党成立之间的内在联系。','[]','①五四运动中，中国工人阶级开始以独立的姿态登上政治舞台并成为运动主力，标志着中国民主革命进入新阶段；②五四运动促进了马克思主义在中国的传播及其同中国工人运动的结合，为中国共产党的成立作了思想上和干部上的准备；③因此五四运动是中国旧民主主义革命走向新民主主义革命的转折点，也是中国共产党成立的思想与阶级基础。','subjective',20);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (39,15,'实验室用过氧化氢溶液和二氧化锰制取氧气时，二氧化锰在反应中充当什么角色？','[\"A. 反应物，被消耗产生氧气\",\"B. 催化剂，加快反应速率且反应前后质量和化学性质不变\",\"C. 生成物，是反应的产物之一\",\"D. 干燥剂，用于吸收氧气中的水蒸气\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (40,15,'下列关于用过氧化氢制取氧气的发生装置与收集方法，说法正确的是？','[\"A. 需要酒精灯加热，属于固固加热型装置\",\"B. 长颈漏斗末端可以不伸入液面以下\",\"C. 属于固液不加热型装置，可用排水法或向上排空气法收集\",\"D. 因为氧气密度比空气小，应用向下排空气法收集\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (41,15,'用排水法收集氧气时，为什么要等到导管口气泡连续均匀冒出后再开始收集，而不是一开始冒气泡就收集？','[]','参考答案：刚开始排出的气泡主要是发生装置和导管内残留的空气，若立即收集，会使收集到的氧气中混有空气而不纯；待气泡连续并比较均匀地冒出时，说明装置内空气已基本排尽，此时开始收集才能得到较纯净的氧气。','subjective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (48,18,'在直角三角形中，两直角边分别为 6 和 8，则斜边长为：','[\"A. 7\",\"B. 10\",\"C. 12\",\"D. 14\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (49,18,'下列各组数中，是勾股数的是：','[\"A. 1,2,3\",\"B. 2,3,4\",\"C. 5,12,13\",\"D. 4,5,6\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (50,18,'一架 13 米长的梯子斜靠在墙上，梯子底端距墙 5 米，求梯子顶端距地面的高度。','[]','参考答案：设高度为 h，由勾股定理 h²+5²=13²，即 h²=169−25=144，故 h=12 米。梯子顶端距地面 12 米。','subjective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (51,19,'新文化运动高举的两面大旗是？','[\"A. 自强与求富\",\"B. 民主与科学\",\"C. 自由与平等\",\"D. 民权与民生\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (52,19,'标志着中国工人阶级开始以独立姿态登上政治舞台的事件是？','[\"A. 辛亥革命\",\"B. 新文化运动\",\"C. 五四运动\",\"D. 中共一大\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (53,19,'中国第一个共产党早期组织的建立者和地点是？','[\"A. 李大钊 北京\",\"B. 陈独秀 上海\",\"C. 毛泽东 长沙\",\"D. 董必武 武汉\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (54,19,'为什么说中国共产党的成立是\"开天辟地的大事变\"？请结合史实简要分析。','[]','①中国共产党是新型无产阶级革命政党，以马克思主义为指导；②使中国革命有了坚强的领导核心，中国人民有了可依赖的组织者和领导者；③使中国革命有了科学的指导思想、明确的奋斗目标和新的革命方法；④从此中国革命面貌焕然一新，推动中国革命不断走向胜利。','subjective',20);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (64,23,'在长度为 n 的有序数组上，二分查找的时间复杂度是？','[\"A. O(n)\",\"B. O(log n)\",\"C. O(n²)\",\"D. O(1)\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (65,23,'对升序数组执行二分查找，若 a[mid] < target，应如何调整指针？','[\"A. R = mid - 1\",\"B. L = mid + 1\",\"C. R = mid\",\"D. L = mid\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (66,23,'二分查找的必要前提条件是？','[\"A. 数组元素必须是整数\",\"B. 数组长度必须是 2 的幂\",\"C. 数组必须有序\",\"D. 数组必须无重复元素\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (67,23,'思考与探究：若数组中存在多个与 target 相等的元素（例如 [2,5,7,7,7,9,12]），标准二分查找返回的是哪一个？如何改造算法以返回第一个等于 target 的下标？','[]','标准二分查找返回的是区间收缩过程中最先遇到的相等元素，不保证是第一个或最后一个。要返回第一个等于 target 的下标：当 a[mid]===target 时不立即返回，而是令 R=mid-1 继续向左收缩；循环结束后若 L 未越界且 a[L]===target，则 L 即为第一个相等元素的位置。要返回最后一个，则遇到相等时令 L=mid+1，最后检查 R。','subjective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (68,24,'快速排序的平均时间复杂度是？','[\"A. O(n)\",\"B. O(n²)\",\"C. O(nlogn)\",\"D. O(logn)\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (69,24,'当基准选在左端 a[l] 时，划分阶段应先移动哪个指针？','[\"A. 先移动 i（左指针）\",\"B. 先移动 j（右指针）\",\"C. 两个指针同时移动\",\"D. 顺序无关紧要\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (70,24,'关于快速排序，下列说法正确的是？','[\"A. 是稳定排序\",\"B. 最坏时间复杂度为 O(nlogn)\",\"C. 划分后需要合并两个子区间\",\"D. pivot 归位后其左侧都 ≤ 它，右侧都 ≥ 它\"]','D','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (71,24,'为什么当基准取在左端时，划分要先移动右指针 j？如果反过来先动 i 会发生什么？请用一个具体数组举例说明。','[]','参考答案：因为基准在左端，最终 pivot 要与相遇点交换，相遇点的值必须 ≤ pivot 才能保证交换后左侧都 ≤ pivot。先动 j（从右找 < pivot 的数）能保证 i、j 相遇时，相遇位置的元素一定 ≤ pivot。若先动 i，i 可能停在一个 > pivot 的位置与 j 相遇，交换后会把大于 pivot 的数换到 pivot 左边，破坏划分正确性。例如 [6,1,2,7,9]，若先动 i，i 会停在 7 与 j 相遇，交换后 7 跑到最左端，划分错误。','subjective',15);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (78,27,'对数组执行一次 partition 划分后，基准元素的位置具有什么特点？','[\"A. 它是整个数组的最小值\",\"B. 它左边的元素都 ≤ 它，右边的元素都 > 它，且已在最终位置\",\"C. 它一定位于数组正中间\",\"D. 它与相邻元素构成逆序对\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (79,27,'快速排序的平均时间复杂度和最坏时间复杂度分别是？','[\"A. O(n) 和 O(n log n)\",\"B. O(n log n) 和 O(n log n)\",\"C. O(n log n) 和 O(n²)\",\"D. O(n²) 和 O(n²)\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (80,27,'如果输入数组已经是升序的，使用「总是选最右元素作为 pivot」的快排会发生什么？可以如何优化？','[]','若数组已升序且总选最右元素为 pivot，则每次划分后基准都落在区间端点，左右子区间长度为 0 和 n-1，递归深度退化为 n，时间复杂度变为 O(n²)，且递归栈可能溢出。优化方法：① 随机选择 pivot；② 三数取中（首、中、尾三者取中位数）；③ 当子区间较小时切换为插入排序；④ 使用尾递归优化减少栈深度。','subjective',15);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (87,30,'下列哪一项表示“一个苹果”？','[\"A. a apple\",\"B. an apple\",\"C. apple\",\"D. the apples\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (88,30,'apple 的正确音标是？','[\"A. /eɪpl/\",\"B. /əˈpl/\",\"C. /ˈæpl/\",\"D. /ˈɑːpl/\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (89,30,'请用 apple 分别造一个“喜欢苹果”和“喝苹果汁”的英文句子，并注意冠词和单复数。','[]','参考答案：① I like apples. / I like eating apples. 我喜欢（吃）苹果。② I\'d like some apple juice. 我想要一些苹果汁。表一类事物时 apple 常用复数 apples；apple juice 为不可数名词短语，可用 some 修饰。','subjective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (93,32,'快速排序的平均时间复杂度是？','[\"A. O(n)\",\"B. O(nlogn)\",\"C. O(n²)\",\"D. O(logn)\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (94,32,'对数组 [5,3,8,1,9] 以首元素 5 为基准做一次分区（Partition）后，5 的最终位置（下标从0开始）可能是？','[\"A. 0\",\"B. 2\",\"C. 3\",\"D. 4\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (95,32,'思考与探究：为什么快速排序在数组已经有序时，如果总选第一个元素作为基准，会退化到 O(n²)？如何避免？','[]','参考答案：数组已有序时，选首元素作基准，每次分区后 pivot 都落在端点，导致一个子区间长度为 n-1、另一个为 0，递归树退化成链，总比较次数为 n+(n-1)+…+1 = n(n-1)/2，即 O(n²)。避免方法：随机选择基准、三数取中（首中尾选中位数），或改用三路快排处理大量重复元素。','subjective',15);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (96,33,'两个质点相距 r 时引力为 F，若将两质点质量都加倍、距离也加倍，则引力大小为：','[\"A. F\",\"B. 2F\",\"C. 4F\",\"D. F/4\"]','A','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (97,33,'关于万有引力，下列说法正确的是：','[\"A. 只有天体之间才存在万有引力\",\"B. 两物体间的引力大小与距离成反比\",\"C. 两物体相互吸引，彼此的引力大小相等\",\"D. 地球对苹果的引力大于苹果对地球的引力\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (98,33,'为什么我们在生活中很难感受到两个普通物体之间的万有引力？请结合引力常量 G 的数值加以说明。','[]','引力常量 G=6.67×10⁻¹¹ N·m²/kg²，数值极小；普通物体质量在千克量级，代入 F=G·m₁m₂/r² 算得的引力通常只有 10⁻⁷~10⁻⁹ N 量级，远小于摩擦力、重力等常见力，因此人体难以察觉；只有当至少一方质量达到天体级别时，引力才表现得十分显著。','subjective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (99,34,'自由泳打腿的主要发力部位是？','[\"A. 膝盖\",\"B. 髋部（大腿根部）\",\"C. 脚踝\",\"D. 小腿\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (100,34,'自由泳换气时，正确的头部动作是？','[\"A. 抬头把整个脸抬出水面\",\"B. 不转头，直接把嘴抬出水面\",\"C. 配合转肩侧转头，半脸在水中\",\"D. 仰起脖子用力吸气\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (101,34,'为什么自由泳要强调\"高肘抱水\"？如果划水时肘部下沉（拖肘）会有什么问题？','[]','参考答案：高肘抱水能让前臂和手掌尽可能正对后方，增大对水面，形成有效的\"划水桨面\"，把水牢牢\"抱\"住再向后推，从而获得更大的推进力。如果肘部下沉（拖肘），手臂与水面平行或滑过水面，对水面变小，水会从肘下溜走，划水效率大幅下降，还容易造成肩部损伤。高肘的关键是入水后屈肘、肘高于手掌和前臂。','subjective',15);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (102,35,'800米起跑通常采用哪种姿势？','[\"A. 蹲踞式起跑\",\"B. 站立式起跑\",\"C. 半蹲踞式起跑\",\"D. 行进间起跑\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (103,35,'站立式起跑\"预备\"动作时，身体重心应位于？','[\"A. 完全落在后脚，上体直立\",\"B. 均匀落在两脚，上体稍后仰\",\"C. 主要落在前脚，上体前倾\",\"D. 完全抬起，准备跳跃\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (104,35,'800米起跑后加速段的合理距离大约是？','[\"A. 3~5米即可抬头直腰\",\"B. 20~30米后逐渐进入途中跑\",\"C. 全程冲刺直到终点\",\"D. 100米后才开始加速\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (105,36,'中国手语中表达“我”时，正确的动作是？','[\"A. 手掌拍胸口\",\"B. 拇指指向自己\",\"C. 食指指向自己胸部\",\"D. 双手交叉放胸前\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (106,36,'国际通用 ILY 单手“我爱你”手势中，哪几根手指需要伸直？','[\"A. 食指、中指、无名指\",\"B. 拇指、食指、小指\",\"C. 拇指、中指、小指\",\"D. 五指全部张开\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (107,36,'思考与探究：为什么中国手语中“爱”的动作要配合贴胸？','[]','参考答案：① 在中国文化与手语表达中，“心”位于胸口，是情感的载体，贴胸动作象征“发自内心的爱”；② 贴胸使动作具有方位指向和情感指向，与单纯的手部动作区分开，增强语义辨识度；③ 体现手语“象似性”特点，即动作模拟情感所在位置，便于理解和记忆。','subjective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (108,37,'在长度为 1024 的有序数组中使用二分查找，最坏情况下需要比较的次数约为？','[\"A. 10 次\",\"B. 11 次\",\"C. 512 次\",\"D. 1024 次\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (109,37,'对升序数组执行二分查找，当 a[m] < target 时，下一步应当：','[\"A. r = m - 1\",\"B. l = m + 1\",\"C. r = m\",\"D. l = m\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (110,37,'思考与探究：为什么二分查找要求数组必须有序？如果数组允许重复元素，二分查找还能正常工作吗？返回的是哪个位置？','[]','参考答案：①只有有序才能保证“中间值小于目标时目标必在右半、大于目标时必在左半”，从而安全折半；乱序时该推论不成立，会误删真正的答案区间。②允许重复元素时二分查找仍可运行，但返回的下标不一定是第一个（或最后一个）等于 target 的位置；若要找左边界或右边界，需要在命中后继续收缩对应一侧的区间，直到 l>r 再根据位置判定。','subjective',15);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (111,38,'对数组执行一趟快速排序分区后，一定成立的结论是：','[\"A. 整个数组已经有序\",\"B. 基准元素到达其最终位置\",\"C. 左右两个子数组长度相等\",\"D. 所有元素都比基准小\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (112,38,'快速排序的平均时间复杂度和最坏时间复杂度分别是：','[\"A. O(n) 和 O(n log n)\",\"B. O(n log n) 和 O(n log n)\",\"C. O(n log n) 和 O(n²)\",\"D. O(n²) 和 O(n²)\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (113,38,'为什么快速排序被称为\"不稳定\"排序？请举例说明什么场景下不稳定性会造成问题。','[]','参考答案：稳定性指相等元素在排序前后相对次序保持不变。快速排序在分区交换时，可能把后面相等的元素越过前面相等的元素交换到前面，从而打乱相对顺序。例如按\"成绩\"排序时，若两同学分数相同、希望保持原录入顺序（学号升序），快排可能交换他们的位置，导致次序错乱。对多关键字排序或要求保持原始次序的业务场景，应选择稳定排序（如归并排序）。','subjective',15);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (114,39,'下列关于 apple 的冠词使用，正确的是？','[\"A. a apple\",\"B. an apple\",\"C. the apple（只能用 the）\",\"D. / apple（不加冠词）\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (115,39,'apple 的英式音标，下列哪一项正确？','[\"A. /eɪpl/\",\"B. /əˈpl/\",\"C. /ˈæpl/\",\"D. /ˈɑːpl/\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (116,39,'思考与探究：请用 apple 写一个包含短语或谚语的完整句子，并说明句中冠词为什么用 an。','[]','参考答案：例如 “An apple a day keeps the doctor away.” 或 “I\'d like an apple pie.” 使用 an 是因为 apple 以元音音素 /æ/ 开头，不定冠词在元音音素前要用 an 而不是 a，这是按发音而非按字母决定的。','subjective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (117,40,'下列哪个选项是 apple 的正确音标？','[\"A. /eɪpl/\",\"B. /ˈæpl/\",\"C. /ˈɑːpl/\",\"D. /əˈpleɪ/\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (118,40,'句子“I have ___ apple.”空格处应填？','[\"A. a\",\"B. the\",\"C. an\",\"D. /（不填）\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (119,40,'思考与探究：请用 apple 造两个句子，一个用单数 an apple，一个用复数 apples，并各写一句中文翻译。','[]','参考答案：① There is an apple on the table. 桌子上有一个苹果。② My mother buys some red apples every week. 我妈妈每周都买一些红苹果。要点：元音音素开头用 an；泛指一类事物时可数名词用复数 apples。','subjective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (120,41,'\"一个苹果\"的正确英文表达是？','[\"A. a apple\",\"B. an apple\",\"C. the apple\",\"D. apple\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (121,41,'apple 的正确音标（英式/美式）是？','[\"A. /eɪpl/\",\"B. /əˈpl/\",\"C. /ˈæpl/\",\"D. /ˈɑːpl/\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (122,41,'请用 apple 造一个完整的英文句子，至少包含一个搭配（如 apple juice / apple pie / an apple a day）。','[]','参考答案：例如 \"I would like a glass of apple juice.\"（我想要一杯苹果汁。）或 \"An apple a day keeps the doctor away.\"（一天一苹果，医生远离我。）注意冠词 an 的使用，以及 apple 作定语修饰其他名词时用单数形式。','subjective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (126,43,'冬季，北印度洋表层洋流的整体方向是：','[\"A. 顺时针\",\"B. 逆时针\",\"C. 自南向北\",\"D. 自东向西\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (127,43,'中低纬大洋环流形成的主要动力是：','[\"A. 潮汐与海啸\",\"B. 海水密度差异\",\"C. 盛行风与地转偏向力\",\"D. 河流入海径流\"]','C','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (128,43,'冬季，驱动北印度洋洋流反转的盛行风是：','[\"A. 东北季风\",\"B. 西南季风\",\"C. 东南信风\",\"D. 盛行西风\"]','A','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (129,43,'说明北印度洋冬季逆时针环流的形成过程，并解释索马里沿岸夏季为什么会出现寒流。','[]','参考答案：冬季亚洲大陆降温快，形成高压，印度洋上空盛行东北季风。东北季风把阿拉伯海和孟加拉湾的表层海水向西、向南推，海水沿索马里沿岸南下，到赤道附近转向东流，再进入孟加拉湾，整体呈逆时针方向。夏季盛行西南季风，索马里沿岸表层海水被吹离海岸，深层冷水上泛形成上升流，水温显著低于周围海面，因此形成寒流。','subjective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (138,46,'原题中圆心 C 到直线 y=√3·x+2 的距离 d 等于（　）','[\"A. 1\",\"B. 2\",\"C. √3\",\"D. 4\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (139,46,'原题中 r 的取值范围是（　）','[\"A. (0,1)\",\"B. (1,3)\",\"C. [1,3]\",\"D. (3,+∞)\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (140,46,'若将“距离为 1 的点有且仅有 2 个”改为“恰有 3 个”，求 r 的值并说明理由。','[]','参考答案：当 r=d+1=3 时，圆与距直线较远的那条平行线相切（1 个点），与较近的那条平行线相交（2 个点），合计 3 个点，故 r=3。','subjective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (141,47,'下列哪一项是“一个苹果”的正确表达？','[\"A. a apple\",\"B. an apple\",\"C. the apple\",\"D. apple\"]','B','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (142,47,'apple 一词中不发音的字母是？','[\"A. a\",\"B. p\",\"C. l\",\"D. e\"]','D','objective',10);
INSERT INTO `question` (`id`, `animation_id`, `question_text`, `options`, `answer`, `question_type`, `score`) VALUES (143,47,'请用 apple 造一个句子，并说明 an apple 与 apples 在用法上的区别。','[]','参考答案：例句如 I eat an apple every day.（我每天吃一个苹果）。区别：an apple 表示“一个苹果”，是单数可数名词，因 apple 以元音音素 /æ/ 开头，冠词用 an 不用 a；apples 是复数形式，可表示多个苹果或泛指一类苹果，如 I like apples.（我喜欢苹果）。','subjective',15);
