INSERT INTO `answer_record` (`id`, `task_id`, `question_id`, `student_id`, `answer_text`, `is_correct`, `score`, `submit_time`) VALUES (989,19,140,30,'当 r=3 时，圆心到直线距离 d=2。距离直线为 1 的两条平行线中，较远一条与圆相切得到 1 个点，较近一条与圆相交得到 2 个点，合计 3 个点，所以 r=3。',NULL,0,'2026-11-24 16:00:16');
INSERT INTO `answer_record` (`id`, `task_id`, `question_id`, `student_id`, `answer_text`, `is_correct`, `score`, `submit_time`) VALUES (990,19,138,31,'B',1,10,'2026-11-24 16:00:16');
INSERT INTO `answer_record` (`id`, `task_id`, `question_id`, `student_id`, `answer_text`, `is_correct`, `score`, `submit_time`) VALUES (991,19,139,31,'B',1,10,'2026-11-24 16:00:16');
INSERT INTO `answer_record` (`id`, `task_id`, `question_id`, `student_id`, `answer_text`, `is_correct`, `score`, `submit_time`) VALUES (992,19,140,31,'d=|0+2|/√((√3)^2+(-1)^2)=2。距离为 1 的两条平行线：r=d+1=3 时，较远一条与圆相切（1 点）、较近一条与圆相交（2 点），共 3 点，故 r=3。',NULL,0,'2026-11-24 16:00:16');
INSERT INTO `answer_record` (`id`, `task_id`, `question_id`, `student_id`, `answer_text`, `is_correct`, `score`, `submit_time`) VALUES (993,19,138,32,'A',0,0,'2026-11-24 16:00:16');
INSERT INTO `answer_record` (`id`, `task_id`, `question_id`, `student_id`, `answer_text`, `is_correct`, `score`, `submit_time`) VALUES (994,19,139,32,'D',0,0,'2026-11-24 16:00:16');
INSERT INTO `answer_record` (`id`, `task_id`, `question_id`, `student_id`, `answer_text`, `is_correct`, `score`, `submit_time`) VALUES (995,19,140,32,'我觉得 r 应该取 1，因为距离是 1，半径取 1 圆上到直线距离为 1 的点就有 3 个了。',NULL,0,'2026-11-24 16:00:16');
INSERT INTO `answer_record` (`id`, `task_id`, `question_id`, `student_id`, `answer_text`, `is_correct`, `score`, `submit_time`) VALUES (996,19,138,33,'B',1,10,'2026-11-24 16:00:16');
INSERT INTO `answer_record` (`id`, `task_id`, `question_id`, `student_id`, `answer_text`, `is_correct`, `score`, `submit_time`) VALUES (997,19,139,33,'B',1,10,'2026-11-24 16:00:16');
INSERT INTO `answer_record` (`id`, `task_id`, `question_id`, `student_id`, `answer_text`, `is_correct`, `score`, `submit_time`) VALUES (998,19,140,33,'d=2。r=d+1=3 时，与较远平行线相切（1 点）、与较近平行线相交（2 点），共 3 点，符合题意，故 r=3。',NULL,0,'2026-11-24 16:00:16');
