INSERT INTO `courseware_feedback` (`id`, `animation_id`, `student_id`, `student_name`, `type`, `content`, `created_at`) VALUES (10,3,17,'郑凯文','evaluation','最终版的动画最流畅，查找过程配合音效反馈，学习体验很好。','2026-09-12 19:00:00');
